import{z as l,x as s,o as E,c as p,q as B,j as t,D as e,d as n,s as o,S as A,b as i}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"独立私人价值与一价","description":"","frontmatter":{"title":"独立私人价值与一价","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ipv-first-price.md","filePath":"econ/ipv-first-price.md","lastUpdated":1791063341000}'),d={name:"econ/ipv-first-price.md"};function c(h,a,m,v,b,u){const r=s("Mermaid");return E(),p("div",null,[a[2]||(a[2]=B('<h1 id="独立私人价值与一价" tabindex="-1">独立私人价值与一价 <a class="header-anchor" href="#独立私人价值与一价" aria-label="Permalink to &quot;独立私人价值与一价&quot;">​</a></h1><div class="epigraph"><p>独立私值下，第一价格密封的对称均衡是把出价写成估值的递增函数：赢者付出自己的报价，因而必须遮挡。</p><footer>—— 据 Riley and Samuelson, Optimal Auctions, American Economic Review, 1981；Krishna, Auction Theory 整理</footer></div><p><a href="/econ/intuitive-criterion">上一课</a>把信号博弈的路径外信念砍到可用。缺口换对象：一件不可分物品，估值是私型，规则是密封一价——最高价得物、付自己的价。不再用教育当信号，用出价。本课钉 IPV 下第一价格的<a href="/econ/bayesian-nash">贝叶斯纳什</a>，不写显示原理，也不把二价的占优真话提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 人，估值 \\(v_i\\) 独立同分布，cdf \\(F\\)，密度 \\(f\\)，支撑 \\([0,\\bar v]\\)。风险中性，物品对每人的价值就是自己的 \\(v_i\\)（独立私人价值，IPV）。第一价格密封：同时出价 \\(b_i\\)，最高者得物并支付 \\(b_i\\)，其余支付零。</p><p>对称 BNE 是递增函数 \\(b(\\cdot)\\)。类型 \\(v\\) 选报 \\(b\\)，赢的概率是 \\(F^{n-1}(b^{-1}(b))\\)，期望支付为该概率乘 \\((v-b)\\)。一阶条件给出遮挡：</p> \\[b(v)=v-\\frac{\\int_{0}^{v}F^{n-1}(t)\\,dt}{F^{n-1}(v)}. \\]<p>均匀 \\([0,1]\\) 时 \\(b(v)=\\frac{n-1}{n}v\\)。出价低于估值，因为报价既决定是否赢，也决定赢了付多少。</p><p><span class="marginnote">数字实例：\\(n=2\\)、均匀 \\([0,1]\\) 时 \\(b(v)=v/2\\)——估值 0.8 的人只报 0.4；\\(n=10\\) 时同一人报 0.72。竞争者翻倍，遮挡就被挤薄。报得低不是胆小：一旦赢，付的是自己的价，报太高等于把本可留下的钱白送出去。</span></p><h3 id="不是完全信息的伯川德" tabindex="-1">不是完全信息的伯川德 <a class="header-anchor" href="#不是完全信息的伯川德" aria-label="Permalink to &quot;不是完全信息的伯川德&quot;">​</a></h3><p>若 \\(v\\) 公开，两人会把价抬到第二高估值附近（或一价下的公开竞价）。IPV 里你不知道别人的 \\(v\\)，最优遮挡依赖 \\(F\\) 与 \\(n\\)。人数上升，竞争更狠，遮挡变薄。先验一变，均衡函数就变——这是 BNE，不是占优策略。</p><p><span class="marginnote">独立是先验：别人的 \\(v\\) 不更新你对物品的评价。共同价值或关联价值下，赢了本身是坏消息（赢家诅咒），出价还要再削，解概念仍是 BNE，积分核不同。那是后课，本课 IPV 最瘦。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：对称 IPV、风险中性、无预算约束、单一物品。先猜对称递增纯策略均衡，用包络或直接对 \\(b\\) 求导，边界 \\(b(\\underline{v})=\\underline{v}\\)（或 \\(0\\)）。再验证二阶：单交叉保证局部最优即全局。</p><p>Riley–Samuelson、Myerson 把同一问题收到直接机制上的虚拟估值；本课停在间接机制「一价密封」的 BNE，不把最优拍卖展开。Krishna 的教科书计算是本课的操作标准。</p>',15)),(E(),t(A,null,{default:e(()=>[o(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E4%BF%A1%E5%8F%B7%E5%8D%9A%E5%BC%88%EF%BC%9A%E8%B7%AF%E5%BE%84%E5%A4%96%20%CE%BC%22%5D%20--%3E%20AUC%5B%22%E8%A7%84%E5%88%99%E5%86%99%E6%AD%BB%EF%BC%9A%E5%AF%86%E5%B0%81%E5%87%BA%E4%BB%B7%22%5D%0A%20%20IPV%5B%22IPV%EF%BC%9A%E4%BB%B7%E5%80%BC%20%3D%20%E8%87%AA%E5%B7%B1%E7%9A%84%20v%22%5D%20--%3E%20FP%5B%22%E4%B8%80%E4%BB%B7%EF%BC%9A%E4%BB%98%E8%87%AA%E5%B7%B1%E7%9A%84%E4%BB%B7%22%5D%0A%20%20FP%20--%3E%20SHADE%5B%22BNE%EF%BC%9Ab(v)%20%EF%BC%9C%20v%EF%BC%8C%E4%BE%9D%E8%B5%96%20F%E3%80%81n%22%5D%0A%20%20SHADE%20--%3E%20SP%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%BA%8C%E4%BB%B7%EF%BC%8C%E5%8D%A0%E4%BC%98%E7%9C%9F%E8%AF%9D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[n("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"遮挡来自边际权衡。略微提高出价：赢率上升（密度项），但赢了时付款上升（概率项）。最优把 \\(v-b(v)\\) 留成「赢率对付款」的保险。\\(F\\) 越往上厚，高类型竞争越密，高 \\(v\\) 的遮挡比例可以下降——均匀例子里比例恒为 \\(1/n\\)。",-1)),(E(),t(A,null,{default:e(()=>[o(r,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAISE%5B%22%E5%87%BA%E4%BB%B7%E6%8A%AC%E9%AB%98%E4%B8%80%E7%82%B9%22%5D%20--%3E%20WIN%5B%22%E8%B5%A2%E7%8E%87%E4%B8%8A%E5%8D%87%3A%20%E5%AF%86%E5%BA%A6%E9%A1%B9%22%5D%0A%20%20RAISE%20--%3E%20COST%5B%22%E8%B5%A2%E4%BA%86%E4%BB%98%E5%BE%97%E6%9B%B4%E5%A4%9A%3A%20%E6%A6%82%E7%8E%87%E9%A1%B9%22%5D%0A%20%20WIN%20--%3E%20BAL%5B%22%E4%B8%A4%E8%BE%B9%E7%9B%B8%E6%8A%B5%E5%A4%84%E5%AE%9A%E5%9D%87%E8%A1%A1%22%5D%0A%20%20COST%20--%3E%20BAL%0A%20%20NUP%5B%22%E4%BA%BA%E6%95%B0%20n%20%E5%A2%9E%E5%8A%A0%22%5D%20--%3E%20STEEP%5B%22%E8%B5%A2%E7%8E%87%E6%9B%B2%E7%BA%BF%E5%8F%98%E9%99%A1%22%5D%0A%20%20STEEP%20--%3E%20THIN%5B%22%E9%81%AE%E6%8C%A1%E5%8F%98%E8%96%84%2C%20%E5%9D%87%E5%8C%80%E6%97%B6%E9%99%8D%E4%B8%BA%201%2Fn%22%5D%0A%20%20BAL%20--%3E%20THIN%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p>与信号的差别：一价里接收者不选信念去付工资，规则把支付函数钉死。均衡策略仍是类型依存，但路径外「没人出这个价」的信念不再是撑混同的主工具；对称递增均衡在每条路径上都有人出邻近的价。直观标准那一刀这里用不上。</p><p><span class="marginnote">直觉类比：遮挡像自助餐里的「留一手」——报得越接近估值，赢的次数越多，但每赢一次赚的差价越薄；均衡就是选一个让「中奖频率 × 每注利润」最大的留手幅度。留太多总输，留太少白干，两个极端都不划算。</span></p><h3 id="期望支付由赢率函数决定" tabindex="-1">期望支付由赢率函数决定 <a class="header-anchor" href="#期望支付由赢率函数决定" aria-label="Permalink to &quot;期望支付由赢率函数决定&quot;">​</a></h3><p>包络：类型 \\(v\\) 的均衡期望支付等于 \\(\\int^{\\,v} G(t)\\,dt\\)，其中 \\(G\\) 是均衡赢率。一价通过 \\(b(\\cdot)\\) 实施某个 \\(G\\)；二价将实施同一 \\(G\\)（对称 IPV 下最高估值者赢）。收入等价是后课的句子，本课只记下：遮挡不等于卖方少卖钱的直觉，因为二价不遮挡却可能期望收入相同。</p><p><span class="marginnote">不对称先验、风险厌恶、预算上限都会打破对称 \\(b(v)=\\frac{n-1}{n}v\\)。风险厌恶者少遮挡（更怕输）。本课对称风险中性是基准，后课等价定理也站在这一基准上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>保留价、进入费改边界条件，不改「付自己的价 \\(\\Rightarrow\\) 遮挡」。多物品、组合拍卖超出本课。也不要把密封出价写成限价簿的时间优先；这里没有队列，只有一次同时报价。</p><p><span class="marginnote">常见误区：初学者容易以为「报低一点总没坏处，输了也不亏」。实际上报太低会输给本可赢下的对手，把正利润拱手让人——均衡报价比估值低，但绝不是越低越好，每个类型都恰好卡在多抬一分就亏的边际上。</span></p><p>后课默认：IPV 一价的对称 BNE 是递增遮挡函数，形状由 \\(F\\) 与 \\(n\\) 决定；占优真话不是这个规则的性质。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IPV：价值私有且独立；一价付自己的报价。</li><li>对称 BNE 遮挡，\\(b(v)\\lt v\\)，均匀时为 \\(\\frac{n-1}{n}v\\)。</li><li>最优依赖先验，不是占优策略。</li><li>规则写死支付，不再靠路径外信念撑均衡。</li><li>出处：Vickrey, 1961（已含一价）；Riley and Samuelson, <em>AER</em>, 1981；Krishna, <em>Auction Theory</em>。</li></ul>',11))])}const F=l(d,[["render",c]]);export{C as __pageData,F as default};
